#![windows_subsystem = "windows"]
use eframe::egui::{self,Color32};
use std::{path::PathBuf,fs,sync::mpsc,thread};
const APP:&[u8]=include_bytes!("../dist/UltraArchiver.exe");
const SHELL:&[u8]=include_bytes!("../dist/UltraArchiverShell.dll");
struct Setup{path:String,desktop:bool,explorer:bool,busy:bool,status:String,tx:mpsc::Sender<String>,rx:mpsc::Receiver<String>}
impl Default for Setup{fn default()->Self{let(tx,rx)=mpsc::channel();Self{path:std::env::var("LOCALAPPDATA").unwrap_or_default()+"\\Programs\\UltraArchiver",desktop:true,explorer:true,busy:false,status:"Готовий до встановлення".into(),tx,rx}}}
impl eframe::App for Setup{fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){if let Ok(s)=self.rx.try_recv(){self.status=s;self.busy=false;}ctx.request_repaint_after(std::time::Duration::from_millis(120));egui::TopBottomPanel::top("top").show(ctx,|ui|{ui.horizontal(|ui|{ui.label(egui::RichText::new("▰").size(30.).color(Color32::from_rgb(35,145,255)));ui.vertical(|ui|{ui.heading("UltraArchiver Setup");ui.label("Встановлення версії 2.3.0");});});});egui::CentralPanel::default().frame(egui::Frame::none().fill(Color32::from_rgb(14,22,35)).inner_margin(24.)).show(ctx,|ui|{ui.heading("Встановлення UltraArchiver");ui.label("Оберіть папку та додаткові параметри.");ui.add_space(20.);ui.label("Папка встановлення");ui.horizontal(|ui|{ui.text_edit_singleline(&mut self.path);if ui.button("Огляд…").clicked(){if let Some(p)=rfd::FileDialog::new().pick_folder(){self.path=p.display().to_string();}}});ui.add_space(16.);ui.checkbox(&mut self.desktop,"Створити ярлик на робочому столі");ui.checkbox(&mut self.explorer,"Додати команди до контекстного меню Провідника");ui.add_space(20.);ui.separator();ui.label("Буде встановлено:");ui.label("• UltraArchiver.exe — архівний менеджер");ui.label("• UltraArchiverShell.dll — інтеграція з Провідником");ui.add_space(14.);if ui.add_enabled(!self.busy,egui::Button::new("Встановити UltraArchiver").fill(Color32::from_rgb(20,112,225))).clicked(){let path=PathBuf::from(&self.path);let desktop=self.desktop;let explorer=self.explorer;let tx=self.tx.clone();self.busy=true;self.status="Встановлення файлів…".into();thread::spawn(move||{let r=(||->Result<(),String>{fs::create_dir_all(&path).map_err(|e|e.to_string())?;fs::write(path.join("UltraArchiver.exe"),APP).map_err(|e|e.to_string())?;fs::write(path.join("UltraArchiverShell.dll"),SHELL).map_err(|e|e.to_string())?;if desktop{let link=std::env::var("USERPROFILE").unwrap_or_default()+"\\Desktop\\UltraArchiver.lnk";let script=format!("$w=New-Object -ComObject WScript.Shell;$s=$w.CreateShortcut('{}');$s.TargetPath='{}';$s.Save();$d=$w.CreateShortcut('{}');$d.TargetPath='{}';$d.Save()",link.replace("'","''"),path.join("UltraArchiver.exe").display(),std::env::var("APPDATA").unwrap_or_default()+"\\Microsoft\\Windows\\Start Menu\\Programs\\UltraArchiver.lnk",path.join("UltraArchiver.exe").display());let _=std::process::Command::new("powershell").arg("-NoProfile").arg("-WindowStyle").arg("Hidden").arg("-Command").arg(script).creation_flags(0x08000000).status();}if explorer{let dll=path.join("UltraArchiverShell.dll");let _=std::process::Command::new("regsvr32.exe").args(["/s",dll.to_str().unwrap_or("")]).creation_flags(0x08000000).status();}Ok(())})();let _=tx.send(match r{Ok(())=>"Встановлення завершено успішно. Можна запускати UltraArchiver.".into(),Err(e)=>format!("Помилка встановлення: {e}")});});}ui.add_space(10.);ui.label(&self.status);});}}
use std::os::windows::process::CommandExt;
fn main()->eframe::Result<()>{let opt=eframe::NativeOptions{viewport:egui::ViewportBuilder::default().with_inner_size([660.,520.]).with_resizable(false),..Default::default()};eframe::run_native("Встановлення — UltraArchiver",opt,Box::new(|cc|{let mut s=(*cc.egui_ctx.style()).clone();s.visuals=egui::Visuals::dark();s.visuals.window_fill=Color32::from_rgb(14,22,35);s.visuals.panel_fill=Color32::from_rgb(17,27,42);cc.egui_ctx.set_style(s);Ok(Box::new(Setup::default()))}))}
